def validate_tags(tags: list, allowed: list) -> list:
    """闭集校验：只保留在 allowed 里的标签，预设外的丢弃。
    返回去重后的合法标签列表，保持顺序。
    """
    allowed_set = set()
    for allowed_tag in allowed:
        if isinstance(allowed_tag, str):
            allowed_set.add(allowed_tag.strip().lower())

    seen = set()
    result = []
    for tag in tags:
        if not isinstance(tag, str):
            continue
        normalized = tag.strip().lower()
        if normalized in allowed_set and normalized not in seen:
            seen.add(normalized)
            result.append(normalized)

    return result

